 * Conversation states.
 *
 * The MVP deliberately uses SIX states, not the eight suggested, because two
 * pairs collapse without losing information:
 *   - OPEN is not a distinct state: it is the union of every non-CLOSED state.
 *     Managers filter "open" with `status != CLOSED`. Keeping OPEN alongside
 *     ASSIGNED/UNANSWERED would allow contradictory rows (OPEN *and* UNANSWERED).
 *   - ASSIGNED collapses into UNANSWERED: the instant a conversation is assigned
 *     it is by definition awaiting the agent's first reply. A separate ASSIGNED
 *     state would be entered and left in the same execution, so it could never
 *     be observed and would only create ambiguity.
 * This is recorded as a decision in docs/DECISIONS.md.
 */
const STATUS = {
  /** Created but no eligible agent existed. Sits in the unassigned queue. */
  WAITING_FOR_AGENT: 'WAITING_FOR_AGENT',
  /** Assigned to an agent; the customer's latest message has no agent reply yet. */
  UNANSWERED: 'UNANSWERED',
  /** Agent has replied and their reply is the most recent message. */
  REPLIED: 'REPLIED',
  /** Alias of REPLIED from the manager's point of view: ball is in customer's court. */
  WAITING_FOR_CUSTOMER: 'WAITING_FOR_CUSTOMER',
  /** Explicitly ended. Only a human/automation closes; customers never close. */
  CLOSED: 'CLOSED',
  /**
   * Moved out of the working sheet. Set by a human choosing it from the
   * dropdown, which triggers an immediate move to the Archive tab.
   * Like CLOSED it is not an open state, so it frees the agent's capacity.
   */
  ARCHIVED: 'ARCHIVED',
};

/** States that count against an agent's open-conversation capacity. */
const OPEN_STATUSES = [
  STATUS.WAITING_FOR_AGENT,
  STATUS.UNANSWERED,
  STATUS.REPLIED,
  STATUS.WAITING_FOR_CUSTOMER,
];

/** Events that drive transitions. */
const EVENT = {
  CUSTOMER_MESSAGE: 'CUSTOMER_MESSAGE',
  AGENT_MESSAGE: 'AGENT_MESSAGE',
  AGENT_ASSIGNED: 'AGENT_ASSIGNED',
  NO_AGENT_AVAILABLE: 'NO_AGENT_AVAILABLE',
  CLOSE: 'CLOSE',
  REOPEN: 'REOPEN',
};

function isOpenStatus(status) {
  return OPEN_STATUSES.indexOf(status) !== -1;
}

/**
 * Generate a stable internal conversation id.
 *
 * Deliberately NOT the WhatsApp message id: message ids are per-message and
 * change with every message, so using one as a conversation key would create a
 * new "conversation" for every inbound message.
 *
 * Format: CONV-<businessPhoneNumberId>-<customerPhone>-<epochMillis>
 * The business number is part of the key so the same customer messaging two
 * different business numbers yields two independent conversations.
 *
 * The timestamp suffix makes ids unique across REOPEN cycles (a customer who
 * returns after a conversation was closed gets a genuinely new conversation
 * row, preserving the closed one for history).
 */
function generateConversationId(businessPhoneNumberId, customerPhone, nowMs) {
  const ts = nowMs === undefined || nowMs === null ? Date.now() : Number(nowMs);
  const biz = String(businessPhoneNumberId || 'unknown').replace(/[^A-Za-z0-9]/g, '');
  const cust = String(customerPhone || 'unknown').replace(/[^A-Za-z0-9]/g, '');
  return 'CONV-' + biz + '-' + cust + '-' + ts;
}

/**
 * Decide the next state given the current state and an event.
 *
 * Returns the transition rather than mutating, so it is trivially testable and
 * the caller decides how to persist it.
 *
 * @param {string|null} currentStatus  null/'' means "no existing conversation".
 * @param {string} event               One of EVENT.*
 * @param {object} [ctx]
 * @param {boolean} [ctx.reopenClosed=true]  Whether a customer message on a
 *        CLOSED conversation reopens it (see docs/ARCHITECTURE.md).
 * @param {boolean} [ctx.hasAgent=false]     Whether an agent is assigned.
 * @returns {{ next: string, changed: boolean, reason: string }}
 */
function nextStatus(currentStatus, event, ctx) {
  const options = ctx || {};
  const reopenClosed = options.reopenClosed === undefined ? true : !!options.reopenClosed;
  const hasAgent = !!options.hasAgent;
  const current = currentStatus || null;

  const result = (next, reason) => ({
    next,
    changed: next !== current,
    reason,
  });

  switch (event) {
    case EVENT.CUSTOMER_MESSAGE: {
      // A customer message always means the business owes a reply.
      if (current === null) {
        return result(
          hasAgent ? STATUS.UNANSWERED : STATUS.WAITING_FOR_AGENT,
          'new_conversation_from_customer_message'
        );
      }
      if (current === STATUS.CLOSED) {
        if (!reopenClosed) {
          // Configured not to auto-reopen: stay closed, caller creates a new
          // conversation instead.
          return result(STATUS.CLOSED, 'closed_conversation_not_reopened_by_config');
        }
        return result(
          hasAgent ? STATUS.UNANSWERED : STATUS.WAITING_FOR_AGENT,
          'reopened_by_customer_message'
        );
      }
      if (current === STATUS.WAITING_FOR_AGENT) {
        // Still nobody to route to; more messages don't change that.
        return result(STATUS.WAITING_FOR_AGENT, 'still_awaiting_agent');
      }
      // REPLIED / WAITING_FOR_CUSTOMER / UNANSWERED -> the customer spoke last.
      return result(STATUS.UNANSWERED, 'customer_message_awaiting_agent_reply');
    }

    case EVENT.AGENT_ASSIGNED: {
      if (current === STATUS.CLOSED) {
        return result(STATUS.CLOSED, 'cannot_assign_closed_conversation');
      }
      return result(STATUS.UNANSWERED, 'agent_assigned_awaiting_first_reply');
    }

    case EVENT.NO_AGENT_AVAILABLE: {
      if (current === STATUS.CLOSED) {
        return result(STATUS.CLOSED, 'closed_conversation_unchanged');
      }
      return result(STATUS.WAITING_FOR_AGENT, 'no_eligible_agent');
    }

    case EVENT.AGENT_MESSAGE: {
      if (current === STATUS.CLOSED) {
        // An agent messaging a closed conversation reopens it — they are
        // deliberately re-engaging the customer.
        return result(STATUS.REPLIED, 'reopened_by_agent_message');
      }
      return result(STATUS.REPLIED, 'agent_replied');
    }

    case EVENT.CLOSE:
      return result(STATUS.CLOSED, 'closed');

    case EVENT.REOPEN: {
      if (current !== STATUS.CLOSED) {
        return result(current, 'reopen_ignored_not_closed');
      }
      return result(
        hasAgent ? STATUS.UNANSWERED : STATUS.WAITING_FOR_AGENT,
        'manually_reopened'
      );
    }

    default:
      return result(current === null ? STATUS.WAITING_FOR_AGENT : current, 'unknown_event');
  }
}

/**
 * Build the full Conversations row for a brand-new conversation.
 * Field names match docs/GOOGLE_SHEETS_SCHEMA.md exactly (snake_case).
 */
function buildNewConversationRow(input) {
  const i = input || {};
  const nowIso = i.now_iso || new Date().toISOString();
  const conversationId =
    i.conversation_id ||
    generateConversationId(i.business_phone_number_id, i.customer_phone, Date.parse(nowIso));

  return {
    // --- business-facing, kept first so the sheet reads left to right ---
    customer_name: i.customer_name || '',
    customer_phone: i.customer_phone || '',
    assigned_agent_name: i.assigned_agent_name || '',
    status: i.status || STATUS.WAITING_FOR_AGENT,
    // Filled in by a human, never by the system. The update builders must not
    // include these, or a manual entry would be wiped on the next message.
    product: '',
    quantity: '',
    // first_message_at is written once and never updated, so response time can
    // be measured against when the customer first made contact.
    first_message_at: i.last_customer_message_at || nowIso,
    conversation_id: conversationId,
    business_phone_number_id: i.business_phone_number_id || '',
    assigned_agent_id: i.assigned_agent_id || '',
    last_message: i.last_message || '',
    last_message_id: i.last_message_id || '',
    last_message_direction: i.last_message_direction || 'inbound',
    last_customer_message_at: i.last_customer_message_at || nowIso,
    last_agent_message_at: '',
    last_activity_at: nowIso,
    unread: i.unread === undefined ? 'TRUE' : i.unread ? 'TRUE' : 'FALSE',
    created_at: nowIso,
    updated_at: nowIso,
    closed_at: '',
    wa_link: i.wa_link || '',
    // Why the conversation is unassigned, when it is. Empty when assigned.
    unassigned_reason: i.unassigned_reason || '',
  };
}

/**
 * Compute the field updates to apply to an existing conversation when a new
 * inbound customer message arrives. Returns ONLY changed fields, so the caller
 * writes a minimal update (fewer Sheets cells touched = fewer lost concurrent
 * edits).
 */
function buildCustomerMessageUpdate(existing, message, opts) {
  const options = opts || {};
  const nowIso = options.now_iso || new Date().toISOString();
  const current = existing || {};
  const transition = nextStatus(current.status || null, EVENT.CUSTOMER_MESSAGE, {
    reopenClosed: options.reopenClosed,
    hasAgent: !!(current.assigned_agent_id && String(current.assigned_agent_id).trim()),
  });

  const update = {
    status: transition.next,
    last_message: message.preview || message.text || '',
    last_message_id: message.message_id || '',
    last_message_direction: 'inbound',
    last_customer_message_at: message.timestamp_iso || nowIso,
    last_activity_at: message.timestamp_iso || nowIso,
    unread: 'TRUE',
    updated_at: nowIso,
  };

  // Reopening clears the closure timestamp.
  if (current.status === STATUS.CLOSED && transition.next !== STATUS.CLOSED) {
    update.closed_at = '';
  }

  // Refresh the profile name if WhatsApp now gives us one and we had none.
  if (message.customer_name && !current.customer_name) {
    update.customer_name = message.customer_name;
  }

  return { update, transition };
}

/**
 * Compute updates for an outbound agent message that the API accepted.
 * NOTE: 'accepted by the API' is NOT 'delivered to the customer' — delivery is
 * only known from a later status webhook. See docs/ERROR_HANDLING.md.
 */
function buildAgentMessageUpdate(existing, message, opts) {
  const options = opts || {};
  const nowIso = options.now_iso || new Date().toISOString();
  const current = existing || {};
  const transition = nextStatus(current.status || null, EVENT.AGENT_MESSAGE, {
    hasAgent: true,
  });

  const update = {
    status: transition.next,
    last_message: message.preview || message.text || '',
    last_message_id: message.message_id || '',
    last_message_direction: 'outbound',
    last_agent_message_at: message.timestamp_iso || nowIso,
    last_activity_at: message.timestamp_iso || nowIso,
    // The agent has now seen and answered the customer.
    unread: 'FALSE',
    updated_at: nowIso,
  };

  if (current.status === STATUS.CLOSED) {
    update.closed_at = '';
  }

  return { update, transition };
}

/**
 * Determine whether a conversation is eligible for inactivity-based closing.
 * The MVP does NOT auto-close: this only marks eligibility so a human or an
 * explicitly enabled scheduled workflow can act. See docs/DECISIONS.md.
 */
function isInactivityCloseEligible(conversation, opts) {
  const options = opts || {};
  const hours = Number(options.inactivityHours);
  const nowMs = options.now ? new Date(options.now).getTime() : Date.now();
  const c = conversation || {};

  if (!isFinite(hours) || hours <= 0) {
    return { eligible: false, reason: 'INACTIVITY_DISABLED' };
  }
  if (!isOpenStatus(c.status)) {
    return { eligible: false, reason: 'NOT_OPEN' };
  }
  const lastActivity = c.last_activity_at ? Date.parse(String(c.last_activity_at)) : NaN;
  if (isNaN(lastActivity)) {
    return { eligible: false, reason: 'NO_VALID_LAST_ACTIVITY' };
  }
  const idleHours = (nowMs - lastActivity) / 3600000;
  if (idleHours < hours) {
    return { eligible: false, reason: 'STILL_ACTIVE', idle_hours: idleHours };
  }
  return { eligible: true, reason: 'INACTIVE_BEYOND_THRESHOLD', idle_hours: idleHours };
}

/**
 * Count each agent's currently-open conversations directly from the
 * Conversations rows.
 *
 * This is the alternative to the denormalized `Agents.open_conversations`
 * counter. The counter has to be incremented on assignment and decremented on
 * close, and Google Sheets has no atomic compare-and-set, so two executions can
 * read the same value and both write it back — the drift that
 * `recalculateAgentLoad()` in the Apps Script exists to repair. Deriving the
 * number from the rows that actually exist cannot drift, because there is no
 * second copy of the truth to disagree with.
 *
 * The cost is reading the Conversations tab instead of a single cell. The MVP
 * workflow already reads that tab to find the customer's existing conversation,
 * so counting here is free — same rows, one pass.
 *
 * @param {Array<object>} rows  Rows from the Conversations sheet.
 * @returns {object}            Map of agent_id -> open conversation count.
 */
function countOpenConversationsByAgent(rows) {
  const counts = {};

  for (const row of rows || []) {
    if (!row || typeof row !== 'object') continue;

    const agentId = String(row.assigned_agent_id || '').trim();
    if (!agentId) continue;                       // unassigned: nobody's load
    if (!isOpenStatus(String(row.status || '').trim())) continue;

    counts[agentId] = (counts[agentId] || 0) + 1;
  }

  return counts;
}

// ----- scripts/lib/assignment.js -----
/**
 * Agent assignment engine.
 *
 * CANONICAL SOURCE. Unit-tested (tests/assignment/assignment.test.js) and
 * injected into n8n Code nodes by scripts/setup/build-workflows.js.
 *
 * The engine is a PURE FUNCTION of (agents, options) -> decision. It performs
 * no I/O. That is deliberate:
 *   - it is exhaustively testable without Google Sheets or Meta,
 *   - the strategy can change (LEAST_OPEN_CONVERSATIONS -> ROUND_ROBIN) without
 *     touching persistence,
 *   - when the store moves to PostgreSQL, only the caller changes: it will wrap
 *     this call in `SELECT ... FOR UPDATE` / a transaction. See
 *     docs/GOOGLE_SHEETS_TO_POSTGRES.md.
 *
 * See docs/ASSIGNMENT_ALGORITHM.md for the full specification, including the
 * concurrency limitations of Google Sheets as a state store.
 */


const STRATEGIES = {
  LEAST_OPEN_CONVERSATIONS: 'LEAST_OPEN_CONVERSATIONS',
  ROUND_ROBIN: 'ROUND_ROBIN',
};

/** Machine-readable reasons an agent was excluded, recorded for audit. */
const INELIGIBLE = {
  INACTIVE: 'INACTIVE',
  UNAVAILABLE: 'UNAVAILABLE',
  AT_CAPACITY: 'AT_CAPACITY',
  MALFORMED_RECORD: 'MALFORMED_RECORD',
  OUTSIDE_WORKING_HOURS: 'OUTSIDE_WORKING_HOURS',
};

const NO_AGENT_REASON = {
  NO_AGENTS_CONFIGURED: 'NO_AGENTS_CONFIGURED',
  NO_ELIGIBLE_AGENT: 'NO_ELIGIBLE_AGENT',
};

/**
 * Google Sheets returns everything as strings. 'TRUE'/'true'/'1'/'yes' are all
 * truthy in practice because humans edit these cells by hand. Anything
 * unrecognised is treated as FALSE (fail closed: do not route a customer to an
 * agent whose availability we cannot positively confirm).
 */
function parseBoolean(value, defaultValue) {
  if (value === undefined || value === null || value === '') {
    return defaultValue === undefined ? false : defaultValue;
  }
  if (typeof value === 'boolean') return value;
  const v = String(value).trim().toLowerCase();
  if (['true', '1', 'yes', 'y', 'نعم'].indexOf(v) !== -1) return true;
  if (['false', '0', 'no', 'n', 'لا'].indexOf(v) !== -1) return false;
  return defaultValue === undefined ? false : defaultValue;
}

/**
 * Sheets cells arrive as strings and may be blank. Returns `fallback` when the
 * value is not a finite number, so a typo in a spreadsheet cell cannot produce
 * NaN comparisons that silently reorder the queue.
 */
function parseIntSafe(value, fallback) {
  if (value === undefined || value === null || String(value).trim() === '') {
    return fallback;
  }
  const n = Number(String(value).trim());
  if (!isFinite(n)) return fallback;
  return Math.trunc(n);
}

/**
 * Parse an ISO-8601 timestamp to epoch ms. Invalid/blank -> null, which sorts
 * FIRST in the tie-breaker (an agent who has never been assigned should get
 * the next conversation ahead of one who was assigned an hour ago).
 */
function parseTimestamp(value) {
  if (value === undefined || value === null || String(value).trim() === '') return null;
  const t = Date.parse(String(value).trim());
  return isNaN(t) ? null : t;
}

/**
 * Normalize one raw agent row (as read from Google Sheets) into a typed record,
 * and decide eligibility. Never throws on a malformed row — marks it ineligible
 * with MALFORMED_RECORD so one bad spreadsheet row cannot break routing for
 * everyone.
 */
function evaluateAgent(rawAgent, options) {
  const opts = options || {};
  const agent = {
    agent_id: rawAgent && rawAgent.agent_id !== undefined ? String(rawAgent.agent_id).trim() : '',
    name: rawAgent && rawAgent.name !== undefined ? String(rawAgent.name).trim() : '',
    phone: rawAgent && rawAgent.phone !== undefined ? String(rawAgent.phone).trim() : '',
    role: rawAgent && rawAgent.role !== undefined ? String(rawAgent.role).trim() : '',
    active: parseBoolean(rawAgent ? rawAgent.active : undefined, false),
    available: parseBoolean(rawAgent ? rawAgent.available : undefined, false),
    max_open_conversations: parseIntSafe(
      rawAgent ? rawAgent.max_open_conversations : undefined,
      opts.defaultMaxOpenConversations === undefined ? 5 : opts.defaultMaxOpenConversations
    ),
    open_conversations: parseIntSafe(rawAgent ? rawAgent.open_conversations : undefined, 0),
    last_assigned_at_ms: parseTimestamp(rawAgent ? rawAgent.last_assigned_at : undefined),
    last_assigned_at: rawAgent && rawAgent.last_assigned_at ? String(rawAgent.last_assigned_at) : null,
    _raw: rawAgent,
  };

  const ineligibleReasons = [];

  if (!agent.agent_id) {
    ineligibleReasons.push(INELIGIBLE.MALFORMED_RECORD);
  }
  if (!agent.active) ineligibleReasons.push(INELIGIBLE.INACTIVE);
  if (!agent.available) ineligibleReasons.push(INELIGIBLE.UNAVAILABLE);

  // Capacity: a negative or zero max means "cannot take conversations".
  if (agent.max_open_conversations <= 0) {
    ineligibleReasons.push(INELIGIBLE.AT_CAPACITY);
  } else if (agent.open_conversations >= agent.max_open_conversations) {
    ineligibleReasons.push(INELIGIBLE.AT_CAPACITY);
  }

  agent.eligible = ineligibleReasons.length === 0;
  agent.ineligible_reasons = ineligibleReasons;
  return agent;
}

/**
 * Deterministic comparator implementing the documented tie-breaker chain:
 *   1. fewest open_conversations
 *   2. earliest last_assigned_at (never-assigned sorts first)
 *   3. agent_id ascending (lexicographic, stable + deterministic fallback)
 *
 * Step 3 guarantees that two n8n executions given identical agent state pick
 * the SAME agent, which makes the behaviour reproducible in tests and in
 * incident review. It does not by itself prevent double-assignment under
 * concurrency — see docs/ASSIGNMENT_ALGORITHM.md.
 */
function compareLeastOpen(a, b) {
  if (a.open_conversations !== b.open_conversations) {
    return a.open_conversations - b.open_conversations;
  }
  const aTs = a.last_assigned_at_ms;
  const bTs = b.last_assigned_at_ms;
  if (aTs === null && bTs !== null) return -1;
  if (aTs !== null && bTs === null) return 1;
  if (aTs !== null && bTs !== null && aTs !== bTs) return aTs - bTs;
  if (a.agent_id < b.agent_id) return -1;
  if (a.agent_id > b.agent_id) return 1;
  return 0;
}

/**
 * ROUND_ROBIN comparator — provided so the strategy is genuinely pluggable
 * rather than aspirational. Selects the agent whose last assignment is oldest,
 * ignoring current load (capacity is still enforced during eligibility).
 */
function compareRoundRobin(a, b) {
  const aTs = a.last_assigned_at_ms;
  const bTs = b.last_assigned_at_ms;
  if (aTs === null && bTs !== null) return -1;
  if (aTs !== null && bTs === null) return 1;
  if (aTs !== null && bTs !== null && aTs !== bTs) return aTs - bTs;
  if (a.agent_id < b.agent_id) return -1;
  if (a.agent_id > b.agent_id) return 1;
  return 0;
}

const COMPARATORS = {
  [STRATEGIES.LEAST_OPEN_CONVERSATIONS]: compareLeastOpen,
  [STRATEGIES.ROUND_ROBIN]: compareRoundRobin,
};

/**
 * Select the agent who should receive a new conversation.
 *
 * @param {Array<object>} rawAgents  Rows from the Agents sheet (strings are fine).
 * @param {object} [options]
 * @param {string} [options.strategy='LEAST_OPEN_CONVERSATIONS']
 * @param {number} [options.defaultMaxOpenConversations=5]
 * @returns {{
 *   assigned: boolean,
 *   agent: object|null,
 *   status: 'ASSIGNED'|'WAITING_FOR_AGENT',
 *   reason: string|null,
 *   strategy: string,
 *   candidates: Array<object>,   // eligible agents, in selection order
 *   evaluated: Array<object>,    // every agent + why they were excluded
 *   decided_at: string           // ISO timestamp of the decision
 * }}
 *
 * When no agent is eligible the conversation is NOT dropped: the caller must
 * persist status WAITING_FOR_AGENT together with `reason`, and the unassigned
 * queue is retried by the reassignment workflow.
 */
function selectAgent(rawAgents, options) {
  const opts = options || {};
  const strategy = opts.strategy || STRATEGIES.LEAST_OPEN_CONVERSATIONS;
  const comparator = COMPARATORS[strategy] || compareLeastOpen;
  const decidedAt = opts.now ? new Date(opts.now).toISOString() : new Date().toISOString();

  const list = Array.isArray(rawAgents) ? rawAgents : [];
  const evaluated = list.map((a) => evaluateAgent(a, opts));

  if (evaluated.length === 0) {
    return {
      assigned: false,
      agent: null,
      status: 'WAITING_FOR_AGENT',
      reason: NO_AGENT_REASON.NO_AGENTS_CONFIGURED,
      strategy,
      candidates: [],
      evaluated,
      decided_at: decidedAt,
    };
  }

  const candidates = evaluated.filter((a) => a.eligible).sort(comparator);

  if (candidates.length === 0) {
    return {
      assigned: false,
      agent: null,
      status: 'WAITING_FOR_AGENT',
      reason: NO_AGENT_REASON.NO_ELIGIBLE_AGENT,
      strategy,
      candidates: [],
      evaluated,
      decided_at: decidedAt,
    };
  }

  return {
    assigned: true,
    agent: candidates[0],
    status: 'ASSIGNED',
    reason: null,
    strategy,
    candidates,
    evaluated,
    decided_at: decidedAt,
  };
}

/**
 * Overlay live conversation counts onto the agent rows before selection.
 *
 * `selectAgent` reads `open_conversations` off each agent row. By default that
 * value is the denormalized counter maintained in the Agents sheet. Passing the
 * rows through here first replaces it with a count derived from the
 * Conversations sheet (see `countOpenConversationsByAgent` in conversation.js),
 * so selection is based on what is actually open rather than on a counter that
 * can drift.
 *
 * The original counter is preserved as `open_conversations_counter` so an
 * operator comparing the two can see the drift rather than having it silently
 * overwritten.
 *
 * @param {Array<object>} rawAgents  Rows from the Agents sheet.
 * @param {object} loadMap           agent_id -> open count.
 * @returns {Array<object>}          Copies, with open_conversations replaced.
 */
function withLiveLoad(rawAgents, loadMap) {
  const loads = loadMap || {};

  return (rawAgents || []).map(function (agent) {
    if (!agent || typeof agent !== 'object') return agent;
    const id = String(agent.agent_id || '').trim();
    // An agent with no open conversations has no entry in the map, which is
    // zero — not "unknown". Falling back to the stale counter here would
    // reintroduce exactly the drift this function removes.
    const live = Object.prototype.hasOwnProperty.call(loads, id) ? loads[id] : 0;

    return Object.assign({}, agent, {
      open_conversations: live,
      open_conversations_counter: agent.open_conversations,
    });
  });
}

// ----- scripts/lib/classify.js -----
/**
 * Request/product classification.
 *
 * CANONICAL SOURCE. Unit-tested (tests/classify/classify.test.js) and injected
 * verbatim into n8n Code nodes by scripts/setup/build-workflows.js.
 *
 * The category list is NOT hard-coded here. It is read at runtime from the
 * `Categories` tab of the same spreadsheet, so the business can add a product
 * line or reword a keyword without a rebuild, a re-import, or a developer.
 * This file only knows HOW to match, never WHAT to match.
 *
 * Matching is deliberately keyword-based rather than AI:
 *   - deterministic, so the same message always files under the same category,
 *   - free and instant, so it cannot add latency or cost per message,
 *   - fully testable without a network call or an API key.
 * An AI classifier can replace this later behind the same function signature.
 *
 * Arabic is normalized before matching (see normalizeForMatch) because the same
 * word arrives spelled many ways: diacritics, the alef variants, teh marbuta
 * for heh, and the definite article glued to the front of the noun. Without
 * normalization a keyword meaning "air conditioning" would miss every message
 * that wrote it with "al-" attached.
 *
 * Nothing here throws. A malformed Categories row is skipped, and a message
 * that matches nothing gets the fallback category rather than an empty cell.
 */


/** Returned when no category matched, so the column is never blank. */
const UNCLASSIFIED = {
  category_id: 'UNCLASSIFIED',
  category: 'غير مصنّف', // "ghayr musannaf"
};

/** Why a classification came out the way it did (recorded in the audit log). */
const REASON = {
  MATCHED: 'matched',
  NO_TEXT: 'no_text_to_classify',
  NO_CATEGORIES: 'no_active_categories_configured',
  NO_MATCH: 'no_keyword_matched',
};

/* -------------------------------------------------------------------------
   Normalization
   ------------------------------------------------------------------------- */

/** Arabic-Indic and extended Arabic-Indic digits to ASCII. */
function asciiDigits(text) {
  return text.replace(/[٠-٩۰-۹]/g, function (d) {
    const code = d.charCodeAt(0);
    const base = code >= 0x06f0 ? 0x06f0 : 0x0660;
    return String(code - base);
  });
}

/**
 * Fold a string into the form keywords are matched against.
 *
 * Lowercases Latin, strips Arabic diacritics and tatweel, unifies the letter
 * shapes that vary by typist, and turns punctuation into spaces. The result is
 * only ever used for comparison — the original text is what gets stored.
 */
function normalizeForMatch(value) {
  if (value === null || value === undefined) return '';
  let text = String(value).toLowerCase();

  text = asciiDigits(text);

  // Harakat (diacritics) and the decorative tatweel carry no meaning here.
  text = text.replace(/[ً-ٰٟ]/g, '');
  text = text.replace(/ـ/g, '');

  // Unify the letter shapes people spell inconsistently.
  text = text.replace(/[أإآٱ]/g, 'ا'); // alef variants -> alef
  text = text.replace(/ة/g, 'ه');                     // teh marbuta  -> heh
  text = text.replace(/ى/g, 'ي');                     // alef maksura -> yeh
  text = text.replace(/ؤ/g, 'و');                     // waw hamza    -> waw
  text = text.replace(/ئ/g, 'ي');                     // yeh hamza    -> yeh
  text = text.replace(/ء/g, '');                           // bare hamza dropped

  // Everything that is not a letter or digit becomes a separator, so a word
  // followed by a question mark matches the same keyword as the bare word.
  text = text.replace(/[^\p{L}\p{N}]+/gu, ' ');

  return text.trim().replace(/\s+/g, ' ');
}

/** True when a keyword contains Arabic script. */
function hasArabic(value) {
  return /[؀-ۿݐ-ݿ]/.test(value);
}

/* -------------------------------------------------------------------------
   Category rows
   ------------------------------------------------------------------------- */

/** Sheets cells arrive as strings, and humans type TRUE / true / 1 / yes. */
function isActive(value) {
  if (value === undefined || value === null || value === '') return true; // blank = active
  const v = String(value).trim().toLowerCase();
  return v === 'true' || v === '1' || v === 'yes' || v === 'y' || v === 'نعم';
}

/** Blank or non-numeric priority sorts last rather than producing NaN. */
function parsePriority(value) {
  const raw = value === undefined || value === null ? '' : String(value).trim();
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : 9999;
}

/**
 * Split a keywords cell into individual keywords.
 * Accepts the separators people actually type, including the Arabic comma.
 */
function parseKeywords(raw) {
  if (raw === null || raw === undefined) return [];
  return String(raw)
    .split(/[,،|;\n\r]+/)
    .map(function (k) { return normalizeForMatch(k); })
    .filter(function (k) { return k.length > 0; });
}

/**
 * Turn raw `Categories` rows into matchable records, in match order.
 *
 * Order is priority ascending, then category_id ascending. It decides ties, so
 * a complaint row with priority 5 beats a pricing row with priority 20 when a
 * message hits one keyword from each. Determinism matters: the same message
 * must never land in a different category on a re-run.
 */
function parseCategories(rows) {
  const parsed = [];

  for (const row of rows || []) {
    if (!row || typeof row !== 'object') continue;

    const categoryId = String(row.category_id || '').trim();
    const name = String(row.name || '').trim();
    if (!categoryId && !name) continue;      // blank spreadsheet row
    if (!isActive(row.active)) continue;

    const keywords = parseKeywords(row.keywords);
    if (keywords.length === 0) continue;     // nothing to match on

    parsed.push({
      category_id: categoryId || name,
      category: name || categoryId,
      keywords: keywords,
      priority: parsePriority(row.priority),
    });
  }

  parsed.sort(function (a, b) {
    if (a.priority !== b.priority) return a.priority - b.priority;
    return a.category_id < b.category_id ? -1 : a.category_id > b.category_id ? 1 : 0;
  });

  return parsed;
}

/* -------------------------------------------------------------------------
   Matching
   ------------------------------------------------------------------------- */

/**
 * Does `keyword` occur in the already-normalized `text`?
 *
 * Arabic keywords match as substrings on purpose: the definite article and the
 * conjunctions are written joined to the noun, so the bare noun must match
 * inside the prefixed form. Latin keywords match whole tokens instead, because
 * substring matching there produces nonsense — "ac" would match "back".
 * A multi-word keyword always matches as a substring.
 */
function keywordMatches(text, keyword, tokens) {
  if (!keyword) return false;
  if (keyword.indexOf(' ') !== -1) return text.indexOf(keyword) !== -1;
  if (hasArabic(keyword)) return text.indexOf(keyword) !== -1;
  return tokens.indexOf(keyword) !== -1;
}

/**
 * Classify one message.
 *
 * @param {string|null} text      The message text as received (not normalized).
 * @param {Array<object>} rows    Raw rows from the `Categories` sheet.
 * @param {object} [options]
 * @param {object} [options.fallback]  {category_id, category} when nothing matches.
 * @returns {{
 *   category_id: string,
 *   category: string,
 *   matched: boolean,
 *   matched_keywords: string[],
 *   match_count: number,
 *   reason: string
 * }}
 *
 * Never throws. A non-text message (image, location, audio) classifies as the
 * fallback with reason NO_TEXT, which is information, not an error.
 */
function classify(text, rows, options) {
  const opts = options || {};
  const fallback = opts.fallback || UNCLASSIFIED;

  function result(category, reason, matchedKeywords) {
    return {
      category_id: category.category_id,
      category: category.category,
      matched: reason === REASON.MATCHED,
      matched_keywords: matchedKeywords || [],
      match_count: matchedKeywords ? matchedKeywords.length : 0,
      reason: reason,
    };
  }

  const categories = parseCategories(rows);
  if (categories.length === 0) return result(fallback, REASON.NO_CATEGORIES);

  const normalized = normalizeForMatch(text);
  if (!normalized) return result(fallback, REASON.NO_TEXT);

  const tokens = normalized.split(' ');

  // Best match = most keywords hit. `categories` is already in tie-break order
  // and the comparison is strictly greater-than, so the first category to reach
  // a given count keeps it.
  let best = null;
  let bestHits = [];

  for (const category of categories) {
    const hits = category.keywords.filter(function (k) {
      return keywordMatches(normalized, k, tokens);
    });
    if (hits.length > bestHits.length) {
      best = category;
      bestHits = hits;
    }
  }

  if (!best) return result(fallback, REASON.NO_MATCH);
  return result(best, REASON.MATCHED, bestHits);
}

// ===================== end generated block ================================

const events = $('Parse & Normalize Events').all()
  .map((i) => i.json)
  .filter((e) => e && e.kind === 'message');

// Every dedupe_key the Messages sheet already holds for this batch. The
// lookup was filtered by each event's own key, so the union of what came
// back IS the set of keys already stored. No paired-item bookkeeping,
// and it behaves the same for one message or a batch of ten.
const alreadyStored = new Set(
  $('Lookup Duplicate').all()
    .map((i) => i.json)
    .filter((r) => r && r.dedupe_key)
    .map((r) => String(r.dedupe_key))
);

const conversations = $('Read Conversations').all()
  .map((i) => i.json).filter((r) => r && r.conversation_id);
const agentRows = $('Read Agents').all()
  .map((i) => i.json).filter((a) => a && a.agent_id);
const categoryRows = $('Read Categories').all()
  .map((i) => i.json).filter((c) => c && (c.category_id || c.name));

const nowIso = new Date().toISOString();
const reopenClosed = String($env.REOPEN_CLOSED_CONVERSATIONS || 'true') !== 'false';
const strategy = $env.ASSIGNMENT_STRATEGY || 'LEAST_OPEN_CONVERSATIONS';

// Load derived from the conversations that actually exist, NOT from the
// Agents.open_conversations counter. Incremented in memory as we assign,
// so two messages arriving in ONE webhook cannot both go to one agent.
const load = countOpenConversationsByAgent(conversations);

// Conversations decided earlier in this same batch, so a customer who
// sends two messages at once gets one conversation, not two.
const decidedInBatch = {};
const out = [];

for (const event of events) {
  const dedupeKey = String(event.dedupe_key || '');
  if (alreadyStored.has(dedupeKey)) {
    // Meta retried something we already stored. Correct action: nothing.
    console.log(JSON.stringify({
      event: 'duplicate_skipped',
      correlation_id: event.correlation_id,
      dedupe_key: dedupeKey,
    }));
    continue;
  }

  const customerPhone = event.customer_phone_e164 || event.customer_phone || '';
  const batchKey = String(event.business_phone_number_id || '') + '|' + customerPhone;

  // ---- which conversation does this belong to? ----
  let existing = decidedInBatch[batchKey] || null;
  if (!existing) {
    // Scoped to the same business number: one customer messaging two of
    // your numbers must get two independent conversations.
    const mine = conversations.filter((r) =>
      String(r.business_phone_number_id || '') === String(event.business_phone_number_id || '') &&
      String(r.customer_phone || '') === String(customerPhone));
    const byRecency = (a, b) =>
      Date.parse(b.last_activity_at || 0) - Date.parse(a.last_activity_at || 0);
    const open = mine.filter((r) => r.status !== 'CLOSED').sort(byRecency);
    const closed = mine.filter((r) => r.status === 'CLOSED').sort(byRecency);
    existing = open[0] || (reopenClosed ? closed[0] || null : null);
  }

  // ---- classify ----
  // Only real words are classified. A bare image or location has none,
  // and its preview ('[location] ...') would match a keyword like
  // "location" and file a confident false positive.
  const classification = classify(event.has_text ? event.text : null, categoryRows);

  // ---- conversation row ----
  let row;
  let needsAssignment;

  if (existing) {
    const built = buildCustomerMessageUpdate(existing, event, { now_iso: nowIso, reopenClosed });
    // ONLY the changed fields plus the key. The Sheets node maps every
    // top-level field it recognises, so sending the whole existing row
    // back would overwrite a reply a manager typed a second ago.
    row = Object.assign({ conversation_id: existing.conversation_id }, built.update);
    needsAssignment = !String(existing.assigned_agent_id || '').trim();

    // Keep the category the conversation already has unless this message
    // genuinely matched something else. An unmatched follow-up ("tamam,
    // shukran") must not reset the conversation to the fallback category.
    if (classification.matched) row.category = classification.category;
  } else {
    row = buildNewConversationRow({
      customer_phone: customerPhone,
      customer_name: event.customer_name,
      business_phone_number_id: event.business_phone_number_id,
      last_message: event.preview,
      last_message_id: event.message_id,
      last_customer_message_at: event.timestamp_iso,
      wa_link: event.wa_link,
      now_iso: nowIso,
    });
    row.category = classification.category;
    needsAssignment = true;
  }

  // ---- assign ----
  let decision = null;
  if (needsAssignment) {
    decision = selectAgent(withLiveLoad(agentRows, load), { strategy });
    if (decision.assigned) {
      load[decision.agent.agent_id] = (load[decision.agent.agent_id] || 0) + 1;
      row.assigned_agent_id = decision.agent.agent_id;
      row.assigned_agent_name = decision.agent.name;
      row.status = 'UNANSWERED';
      row.unassigned_reason = '';
    } else {
      // Never dropped: it waits in the queue with the reason recorded.
      row.status = 'WAITING_FOR_AGENT';
      row.unassigned_reason = decision.reason || '';
    }
  }

  const assignedAgentId = row.assigned_agent_id !== undefined
    ? row.assigned_agent_id
    : (existing ? existing.assigned_agent_id || '' : '');

  // Remember the decision so the next message in this batch sees it.
  decidedInBatch[batchKey] = Object.assign({}, existing || {}, row, {
    business_phone_number_id: event.business_phone_number_id,
    customer_phone: customerPhone,
    assigned_agent_id: assignedAgentId,
  });

  console.log(JSON.stringify({
    event: 'message_resolved',
    correlation_id: event.correlation_id,
    conversation_id: row.conversation_id,
    created: !existing,
    category: classification.category,
    category_reason: classification.reason,
    assigned_agent_id: assignedAgentId,
    assignment_reason: decision ? (decision.reason || 'assigned') : 'already_assigned',
  }));

  // Context the Messages and Log nodes need. Deliberately NOT a spread of
  // `event`: it carries `customer_phone` in its raw pre-normalization form
  // and `status` meaning something else entirely, and both are
  // Conversations column names. Spreading it would silently overwrite good
  // data with bad. `row` goes LAST so it wins any remaining clash.
  out.push({ json: Object.assign({
    sheet_operation: existing ? 'update' : 'append',
    message_id: event.message_id,
    dedupe_key: event.dedupe_key,
    correlation_id: event.correlation_id,
    message_type: event.message_type,
    message_text: event.preview,
    message_timestamp: event.timestamp_iso,
    supported: event.supported,
    processing_status: event.processing_status,
    sender_phone: customerPhone,
    recipient_phone: event.business_display_phone_number || '',
    media_id: event.media_id || '',
    message_category: classification.category,
    classification_reason: classification.reason,
    matched_keywords: classification.matched_keywords.join(', '),
    agent_id: assignedAgentId,
    log_event_type: decision && !decision.assigned ? 'WAITING_FOR_AGENT' : 'MESSAGE_RECORDED',
    assignment_audit: decision ? decision.evaluated.map((a) => ({
      agent_id: a.agent_id,
      eligible: a.eligible,
      reasons: a.ineligible_reasons,
      open: a.open_conversations,
      max: a.max_open_conversations,
    })) : [],
  }, row) });
}

console.log(JSON.stringify({
  event: 'batch_done',
  received: events.length,
  written: out.length,
  skipped_duplicates: events.length - out.length,
}));

return out;
